intro+='<section class="section"><h2>Reference &amp; languages</h2><p><a href="currency-crypto-code-reference/">Currency codes, crypto tickers and unit names</a></p><p><a href="../zh-hans/" lang="zh-Hans">汇率转换、货币转换器与单位换算指南</a> · <a href="../zh-hant/" lang="zh-Hant">匯率轉換、單位換算與離線使用指南</a></p><p class="fine">Comparisons are written by the publisher of Conversion Calculator Plus, with linked sources and editorial recommendations. They are not independent tests or search-ranking awards.</p></section>'
page('guides/index.html','Conversion guides & app comparisons | Conversion Calculator Plus','Practical conversion calculator guides for travel, metric and imperial measurements, engineering, offline currency and choosing an iPhone app.',intro)
article_lookup={a['slug']:a for a in ARTICLES}
for a in ARTICLES:
 body=a['body'].replace('\\n','\n')
 # Keep table scrolling local to the table, not the entire mobile page.
 body=re.sub(r'(<table\b.*?</table>)',r'<div class="table-wrap">\1</div>',body,flags=re.S)
 sources='<ul>'+''.join(f'<li><a href="{esc(s["url"])}">{esc(s["title"])}</a></li>' for s in a['sources'])+'</ul>'
 related=[article_lookup[s] for s in a.get('relatedSlugs',[]) if s in article_lookup]
 relatedhtml=''.join(f'<li><a href="../{b["slug"]}/">{esc(b["title"])}</a></li>' for b in related)
 text=f'''<article class="article"><header class="article-header"><a class="back" href="../">← All guides</a><p class="eyebrow">{esc(a['category'])} · <time datetime="{DATE}">20 October 2026</time></p><h1>{esc(a['title'])}</h1><p class="article-deck">{esc(a['description'])}</p><p class="byline">By Adysseus, publisher of Conversion Calculator Plus</p></header><div class="article-body">{body}<h2>Sources &amp; editorial notes</h2>{sources}<p>Product details were checked on {DATE}. Features and availability can change. For our app’s current compatibility and local Premium price, check the App Store. Comparisons describe published capabilities and workflow fit.</p><h2>Keep exploring</h2><ul>{relatedhtml}<li><a href="../currency-crypto-code-reference/">Currency and crypto code reference</a></li></ul><div class="article-cta"><h2>Try these conversions in one app.</h2><p>Conversion Calculator Plus combines everyday measurements, engineering tools and currency comparisons.</p><a class="button" href="{APP}">View on the App Store ↗</a></div></div></article>'''
 schema={'@context':'https://schema.org','@type':'Article','headline':a['title'],'description':a['description'],'datePublished':DATE,'dateModified':DATE,'author':{'@type':'Organization','name':'Adysseus','url':BASE+'/'},'publisher':{'@type':'Organization','name':'Adysseus','url':BASE+'/'},'mainEntityOfPage':BASE+'/guides/'+a['slug']+'/'}
